-- =============================================================
-- 订单模块 (order-service) 测试数据
-- DB: order_service  表: cart / orders / order_item / payment
-- 测试用户 (固定 UUID, 对应前端 X-User-Id 头):
--   A = 11111111-1111-1111-1111-111111111111
--   B = 22222222-2222-2222-2222-222222222222
--   C = 33333333-3333-3333-3333-333333333333
-- 订单状态全覆盖: PENDING_PAYMENT×2 / PAID×2 / SHIPPED / COMPLETED / CLOSED / REFUNDED
-- 一致性: PENDING_PAYMENT 订单 created_at 为近 3~5 分钟(避免被 15 分钟超时关单任务立即关闭);
--   PAID+ 订单的库存预扣已确认/释放 -> inventory.frozen=0 (见 inventory.sql 注释)
--   orders.version 初始 0 (乐观锁)
-- 说明: seed 订单不产生 kafka 事件, 状态直接预置为一致终态
-- =============================================================
BEGIN;

TRUNCATE payment, order_item, orders, cart;

